// Generated by scripts.prepare_review_assets from the review template.

const data=JSON.parse(document.getElementById('review-data').textContent),el=id=>document.getElementById(id),key='tracex.evidence-review.'+data.sample_hash;
let state={index:0,reviewer:'',reviews:{}},draft=[];try{state=JSON.parse(localStorage.getItem(key))||state;}catch{}
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{el('notice').textContent='Storage unavailable; export regularly.';}}
el('reviewer').value=state.reviewer;el('reviewer').oninput=e=>{state.reviewer=e.target.value;persist();};
data.rows.forEach((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=r.kind+' '+r.record_id;el('jump').append(o);});
const empty=document.createElement('option');empty.value='';empty.textContent='Select after review…';el('label').append(empty);
Object.entries(data.labels).forEach(([id,definition])=>{const o=document.createElement('option');o.value=id;o.textContent=id+' — '+definition;el('label').append(o);});
function observations(){el('observations').replaceChildren();draft.forEach((o,i)=>{const box=document.createElement('div');box.className='obs';
 for(const [key,choices] of [['field',['vehicle','part','symptom','failure_mode','timing','negation','uncertainty']],['polarity',['affirmed','denied','uncertain']]]){const select=document.createElement('select');select.setAttribute('aria-label',key+' '+(i+1));const blank=document.createElement('option');blank.value='';blank.textContent='Select '+key;select.append(blank);choices.forEach(v=>{const option=document.createElement('option');option.value=v;option.textContent=v;select.append(option);});select.value=o[key]||'';select.onchange=e=>draft[i][key]=e.target.value;box.append(select);}
 for(const field of ['value','quote']){const label=document.createElement('label');label.textContent=field==='quote'?'Exact supporting quotation':'Reviewed interpretation';const input=document.createElement('textarea');input.value=o[field]||'';input.oninput=e=>draft[i][field]=e.target.value;label.append(input);box.append(label);}
 const remove=document.createElement('button');remove.textContent='Remove observation';remove.onclick=()=>{draft.splice(i,1);observations();};box.append(remove);el('observations').append(box);});}
function draw(){const row=data.rows[state.index],r=state.reviews[row.record_id]||{};el('title').textContent=row.kind+' '+row.record_id;el('meta').textContent=[row.make,row.model,row.year,row.datea].filter(Boolean).join(' · ');el('text').textContent=row.text;el('label').value=r.label_id||'';el('notes').value=r.notes||'';draft=structuredClone(r.observations||[]);observations();el('jump').value=state.index;const n=Object.keys(state.reviews).length;el('progressText').textContent=n+' / '+data.rows.length+' reviewed';el('progress').max=data.rows.length;el('progress').value=n;el('prev').disabled=!state.index;el('next').disabled=state.index>=data.rows.length-1;}
function move(i){state.index=i;persist();draw();}el('prev').onclick=()=>move(state.index-1);el('next').onclick=()=>move(state.index+1);el('jump').onchange=e=>move(+e.target.value);el('unreviewed').onclick=()=>{for(let n=1;n<=data.rows.length;n++){const i=(state.index+n)%data.rows.length;if(!state.reviews[data.rows[i].record_id])return move(i);}};
el('add').onclick=()=>{draft.push({});observations();};el('save').onclick=()=>{const row=data.rows[state.index];if(!el('label').value||draft.some(o=>!o.field||!o.polarity||!o.value?.trim()||!o.quote||!row.text.includes(o.quote))){el('notice').textContent='Select a label and complete each observation with an exact source quotation.';return;}state.reviews[row.record_id]={label_id:el('label').value,observations:structuredClone(draft),notes:el('notes').value};persist();draw();el('notice').textContent='Saved this human judgment.';};el('clear').onclick=()=>{delete state.reviews[data.rows[state.index].record_id];persist();draw();};
el('export').onclick=()=>{if(!state.reviewer.trim()||!el('attest').checked||!Object.keys(state.reviews).length){el('notice').textContent='Name, reviewed items and human attestation are required.';return;}const result={pack:data.name,sample_hash:data.sample_hash,reviewer:state.reviewer.trim(),annotation_source:'human',attestation:true,exported_at:new Date().toISOString(),reviews:Object.entries(state.reviews).map(([record_id,r])=>({record_id,...r}))};const u=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=data.name+'-human.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};if(data.rows.length)draw();else el('notice').textContent='This pack has no records.';

